// Story deeds (Randall, 1 Nov 2026; rebuilt 3 Nov 2026 as "tons of achievements, at least two per battle"):
// skill-based achievements woven into each act's story. Shared by the app (which checks a won Story battle
// against what the table showed) and the worker (which only accepts deed ids listed here, once each).
// Every test is data (`when`, read by factsMeet in match-facts.js) over the facts the table showed the
// player: turns you started, life, the board, creatures killed and lost, flyers, tribes, counters, suspend,
// morphs and named cards. scripts/story/sim measures each one in Forge self-play before it ships.
// Act-wide deeds read Story progress: the Chronicler clears all 8 battles with the Story decks,
// Both Sides wins every battle from both seats. `hidden` deeds stay a riddle until earned; a `gold`
// deed is a secret boss's crown.
import {factsMeet} from './match-facts.js';

const deed = (id, act, battle, title, lore, art, when, seat = 'hero', extra = {}) => ({id, act, battle, title, lore, art, when, seat, ...extra});
const hidden = (riddle, extra = {}) => ({hidden: true, riddle, ...extra});
const turnsBy = n => ({myTurns: ['<=', n]}), lifeAtLeast = n => ({minLife: ['>=', n]}), endAtLeast = n => ({endLife: ['>=', n]});
const kills = n => ({kills: ['>=', n]}), flyers = n => ({maxFlyers: ['>=', n]}), power = n => ({maxPower: ['>=', n]}), attackers = n => ({maxAttackers: ['>=', n]});
const bigTurn = n => ({oppBigTurn: ['>=', n]}), gained = n => ({lifeGained: ['>=', n]}), lost = n => ({losses: ['<=', n]}), tribe = (t, n) => ({tribe: [t, '>=', n]});

